function validate([nums, m, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 20000) return 'nums needs 1 to 20000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value of nums is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is from 1 to nums.length.';
  if (!Number.isInteger(m) || m < 1 || m > k) return 'm is from 1 to k.';
  return null;
}

