function maxSum(nums, m, k) {
  let best = 0;
  for (let start = 0; start + k <= nums.length; start++) {
    const slice = nums.slice(start, start + k);
    if (new Set(slice).size < m) continue;
    const total = slice.reduce((a, b) => a + b, 0);
    if (total > best) best = total;
  }
  return best;
}

