function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 9);
    const top = rand() < 0.7 ? int(1, 5) : 1000000000;
    const nums = Array.from({ length: n }, () => int(1, top));
    const k = int(1, n);
    const m = int(1, k);
    return [nums, m, k];
  }
  const n = int(1500, 2000);
  const ranges = [3, 20, 200, 1000000000];
  const top = ranges[Math.floor(rand() * ranges.length)];
  const nums = Array.from({ length: n }, () => int(1, top));
  const k = rand() < 0.5 ? int(1, 40) : int(1, n);
  // Keep m near the number of distinct values a window can hold so some windows qualify and some do not.
  const reachable = Math.min(k, top);
  const m = Math.max(1, Math.min(k, reachable - int(0, 2)));
  return [nums, m, k];
}
